Lemma INVL_brk_dead X st L L' BL LS :
  INVL X st L BL LS ->
  ld_resv L' = ld_resv L -> ld_groups L' = ld_groups L -> ld_metas L' = ld_metas L -> ld_brkreg L' = ld_brkreg L ->
